#!/usr/bin/env python3
"""Writes asm/stream_tests.S from asm/gen/stream.py with the variants that
measured best (build/ps2-hw-test/src/hand/stream.c on the PS2, 2026-11-01)."""
import sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import stream

head = '''# Hand-written R5900 versions of the stream_tests.c kernels (bench variants
# asm and asm-vu0), generated by asm/gen/stream_file.py from asm/gen/
# stream.py (the loops ordered by asm/gen/sched.py). n32 ABI: a of
# stream_saxpy is in $f15. The _pref and the plain kernels are the same: the
# hand-written ones prefetch either way (feature clang adds prefetches to the
# plain C loops too).
#
# Chosen by measuring variants on the PS2 (1 MB arrays as in the bench, MB/s):
#   sum:   lq and MMI paddw, PREF 5 lines ahead: 473 (lw/addu: 399; MMI
#          with no PREF: 441, 3 lines ahead: 461; feature clang 427)
#   scale: lq, psllw, paddw x2, sq, 2 lines per iteration, PREF of input and
#          output 5 lines ahead: 389 (without the output PREF: 370; one line
#          per iteration: 339; feature clang 337)
#   saxpy: FPU mul.s and add.s, PREF 5 lines ahead: 468 (no PREF: 312;
#          feature clang 363); VU0 (asm-vu0) one line per iteration, 6
#          lines ahead: 677 (2 lines per iteration: 526)
# Optimized: yes, all six. count is a multiple of 32.

	.set	noreorder
	.set	noat
	.text
'''
out = [head]
for n in ('stream_sum', 'stream_sum_pref'):
    out.append(stream.sum_(n, 5, 1, True))
for n in ('stream_scale', 'stream_scale_pref'):
    out.append(stream.scale(n, 5, 2, True))
out.append('\n#ifdef ASM_VU0')
for n in ('stream_saxpy', 'stream_saxpy_pref'):
    out.append(stream.saxpy_vu0(n, 6, 1))
out.append('\n#else')
for n in ('stream_saxpy', 'stream_saxpy_pref'):
    out.append(stream.saxpy_fpu(n, 5, 1))
out.append('\n#endif // ASM_VU0\n')
open(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'stream_tests.S'), 'w').write('\n'.join(out))
